class Solution {
public:
    string reverseStr(string s, int k) {
        for (int start = 0; start < (int)s.size(); start += 2 * k) {
            int l = start, r = min(start + k, (int)s.size()) - 1;
            while (l < r) {
                swap(s[l], s[r]);
                l++;
                r--;
            }
        }
        return s;
    }
};
